//! Entries slice — Batch 189 (Plan 185 / Research 221) — the open-jev-fast
//! kernel pack of 5: the fused-CUDA GDN + tree-attention serving backend for
//! Open-Jev-27B (Qwen3.8-27B base — the league lane's own architecture
//! family), 256.0 → 17.3 ms per multi-candidate scoring request on one B300.
//!
//! Source: `lyuyiqi/open-jev-fast` @ `c52b8bb958c1f0d241d4eb7fce4ecd8d885bf1e4`
//! (MIT; docs page CC BY-SA 4.0), served upstream wire pinned at
//! `Zefan-Cai/Open-Jev` @ `3308a15` (MIT). Both clones were `.raw/` ephemerals
//! — deleted after the Research-221 verdict committed; every load-bearing
//! quote below was re-verified VERBATIM at the pins BEFORE deletion (the
//! Batch-31 discipline; the Research note carries the quote sites).
//!
//! Pack composition (the verdict's grades, held at conversion):
//! - G +1 `two-chunk-state-independent-overlap-serial-chunk-recurrence` (A−,
//!   the GOAT lead — 11 vs 24 barriers, bit-identical by construction)
//! - F +1 `ancestor-mask-bit-visibility-block-skip-tree-attention` (B — the
//!   measured ≤384-row dispatch cross-over vs cuDNN IS the regime arm)
//! - B +1 `exact-bf16-domain-activation-lut` (B — 65,536-entry SiLU/sigmoid
//!   tables, bit-exact; anti-arm = the source's OWN gated-RMSNorm negative)
//! - D +1 `shape-bucketed-graph-cache-lru` (B− — bucketed CUDA-Graph cache,
//!   LRU 512, copy-in at replay = the positive instance of the device-pointer
//!   scalar rule)
//! - D +1 `fused-serving-stack-measured-negative-ledger` (the annotation row
//!   — five rejected levers with measured reasons, so a future fork
//!   experiment does not re-run them)
//!   Plus ONE rider (text-only, `entries_gpu_18)`: the split-K fold-at-consumer
//!   epilogue placement on `split-k-two-pass-attention-decode-long-context`.
//!
//! Constraints carried from the verdict: B300-only numbers are provenance,
//! never adoption bars (our 4090/M3 re-measure before any arm lands on our
//! kernels — the measured-GOAT offer rides with the lane-intel notes, not
//! the rule); shape-generic rules, the source's Qwen3.8-27B hardcoded shapes
//! are reference material; fixtures are ORIGINAL minimal reproductions,
//! never pasted source (license hygiene + binary-only distribution rule).

use super::KernelRule;

pub fn entries() -> Vec<KernelRule> {
    vec![
        // ── G: the GOAT lead — chunk n+1's state-INDEPENDENT work executes
        // inside chunk n's barrier interval; the two chunks' serial solve
        // chains run side by side, only the state handoff is sequential.
        // 11 barriers vs 24; bit-identical ("skipped MMA k-steps only ever
        // added exact zeros"). ────────────────────────────────────────────
        KernelRule {
            rule_id: "two-chunk-state-independent-overlap-serial-chunk-recurrence".to_string(),
            gpu_concept: "MECHANISM (barrier-interval overlap in a chunked serial recurrence): in a one-block-per-(sequence, head) chunked recurrence, every per-chunk step that does NOT depend on the carried state — the gate cumsum, the beta scaling, K*K^T, the (I+A)^-1 solve, the u/w construction, the output attention matrix — for chunk n+1 executes INSIDE chunk n's barrier interval, so the two chunks' serial solve chains run side by side and only the state handoff is sequential. The serialization argument is mechanism-level, not 'probably faster': the state-carried dependency chain is 1-4 warps deep while everything else is state-independent, so the barrier count drops 24 -> 11 per 2-chunk item and per-layer time 74 -> 36.5 us on the source's B300 (provenance, never our bar). Bit-identity is BY CONSTRUCTION and stated by the source with its mechanism argument: the skipped MMA k-steps only ever added exact zeros, verified by their two-level test suite (kernel element diff + 64-layer hidden state + end-to-end probability drift 0.0021 @539 tok -> 0.019 @10,722 tok with decisions unchanged). NOT-BENCHABLE here: no validator in this corpus hosts a GDN recurrence win metric — lands as decision content + reference citation (the Batch-136 shape), with the measured-GOAT re-measurement offer riding the lane-intel notes (riir-gpu GDN chunked prefill / riir-infer deltanet lanes re-measure before any adoption). REGIME: chunked serial recurrences with a state-carried dependency (GDN/GLA/RWKV family) at chunk counts >= 2 per block; shared memory must stage BOTH chunks (the source stages R=96 rows). ANTI-REGIME: single-chunk paths (nothing to overlap); state-dependent steps dominating the chunk body (nothing to overlap WITH); smem budgets that cannot hold two chunks (the staging cost eats the overlap). KINSHIP (do not double-count): row-owned-register-blocked-recurrence = state-MATRIX parallelism WITHIN one decode step, decomposing ownership to (head, row) — this changes no ownership at all, it SCHEDULES two existing chunks' state-independent halves into each other's barrier intervals; first-order-affine-recurrence-associative-scan = the scan-ALGEBRA alternative for cheap scalar combines (its own text rules dxd-state recurrences like GDN to chunking — this rule is the scheduling win INSIDE that chunked form, composing rather than competing); chunkwise-parallel-recurrence / recurrent-vs-chunk-dispatch = the sequence-axis split decision one level up; shape-only-plan-row-invariant-kernel = plan invariance under splits (the state handoff here stays sequential by design, so composition-invariance is not the contract — bit-identity to the un-overlapped chunked kernel is). CITE: lyuyiqi/open-jev-fast @ c52b8bb9 -- src/kernels.cu gdn6_item (round 4 C6d) + bench/logs/r4/v6_e2e.log (74 -> 36.5 us/layer, B300), MIT. Batch 189 / Plan 185 / Research 221 (candidate 1, A-).".to_string(),
            ref_shape: "// NAIVE: the chunked serial recurrence processes one chunk at a\n// time — every state-independent step of chunk n+1 WAITS for chunk\n// n's barriers even though it reads nothing chunk n writes.\nconst C: usize = 32; // chunk rows\n\npub fn chunked_recurrence_serial(\n    k: &[f32],\n    beta: &[f32],\n    state: &mut [f32],\n    n_chunks: usize,\n) -> Vec<f32> {\n    let mut out = vec![0.0f32; n_chunks * C];\n    for n in 0..n_chunks {\n        // ---- chunk n: state-INDEPENDENT half ----\n        let gate = gate_cumsum(k, n); // no state read\n        let kk = gram_matrix(k, n); // K*K^T, no state read\n        let inv = solve_cholesky(&kk); // (I+A)^-1, no state read\n        let (u, w) = build_uw(k, beta, n, &gate, &inv); // no state read\n        // ---- barrier: the state-dependent half needs the halves above\n        sync(); // 8 barriers per chunk in this naive shape (24 per item)\n        // ---- chunk n: state-DEPENDENT half ----\n        let attn = output_attention(&u, state); // reads the carried state\n        state_update(state, &w, &attn); // writes the carried state\n        sync();\n        write_out(&mut out, n, &attn);\n        // chunk n+1's gate/gram/solve/uw WAIT here: issued only after\n        // this chunk's state half retires — the barrier interval is idle\n    }\n    out\n}\n\nfn gate_cumsum(_k: &[f32], _n: usize) -> Vec<f32> {\n    vec![0.0; C]\n}\nfn gram_matrix(_k: &[f32], _n: usize) -> Vec<f32> {\n    vec![0.0; C * C]\n}\nfn solve_cholesky(_kk: &[f32]) -> Vec<f32> {\n    vec![0.0; C]\n}\nfn build_uw(_k: &[f32], _b: &[f32], _n: usize, _g: &[f32], _i: &[f32]) -> (Vec<f32>, Vec<f32>) {\n    (vec![0.0; C], vec![0.0; C])\n}\nfn output_attention(_u: &[f32], _state: &[f32]) -> Vec<f32> {\n    vec![0.0; C]\n}\nfn state_update(_s: &mut [f32], _w: &[f32], _a: &[f32]) {}\nfn write_out(_o: &mut [f32], _n: usize, _a: &[f32]) {}\nfn sync() {}".to_string(),
            opt_pattern: "// OPT: two chunks per item — chunk n+1's state-INDEPENDENT half\n// (gate cumsum, beta, K*K^T, the (I+A)^-1 solve, u/w) executes\n// INSIDE chunk n's barrier interval; only the state handoff is\n// sequential. 11 barriers per 2-chunk item (vs 24 naive); the state\n// chain is 1-4 warps deep, everything else overlaps. Bit-identical:\n// the skipped MMA k-steps only ever added exact zeros.\nconst C: usize = 32; // chunk rows\nconst R: usize = 96; // smem stages BOTH chunks' independent halves\n\npub fn chunked_recurrence_two_chunk_overlap(\n    k: &[f32],\n    beta: &[f32],\n    state: &mut [f32],\n    n_chunks: usize,\n) -> Vec<f32> {\n    let mut out = vec![0.0f32; n_chunks * C];\n    // stage chunk 0's independent half BEFORE the loop (the prologue\n    // half of the overlap: it owns no predecessor interval yet)\n    let mut staged = stage_independent(k, beta, 0);\n    for n in 0..n_chunks {\n        if n + 1 < n_chunks {\n            // chunk n+1's independent half runs INSIDE chunk n's\n            // barrier interval — issued before the state half waits\n            staged = stage_independent_overlapping(k, beta, n + 1, &staged, R);\n        }\n        // chunk n: state-dependent half consumes the staged values\n        let attn = output_attention(&staged.u, state);\n        state_update(state, &staged.w, &attn);\n        write_out(&mut out, n, &attn);\n        // ONE barrier serves BOTH: chunk n's state write and chunk n+1's\n        // already-issued independent work retire together — 11 barriers\n        // per 2-chunk item instead of 24\n        sync();\n    }\n    out\n}\n\nstruct Staged {\n    u: Vec<f32>,\n    w: Vec<f32>,\n}\n\nfn stage_independent(k: &[f32], beta: &[f32], n: usize) -> Staged {\n    let gate = gate_cumsum(k, n);\n    let kk = gram_matrix(k, n);\n    let inv = solve_cholesky(&kk);\n    build_uw(k, beta, n, &gate, &inv)\n}\n\nfn stage_independent_overlapping(\n    k: &[f32],\n    beta: &[f32],\n    n: usize,\n    prev: &Staged,\n    _smem_rows: usize,\n) -> Staged {\n    // smem holds BOTH chunks' independent halves (R rows total); the\n    // state half of chunk n-1 reads `prev` while this stages\n    let _ = prev;\n    stage_independent(k, beta, n)\n}\n\nfn gate_cumsum(_k: &[f32], _n: usize) -> Vec<f32> {\n    vec![0.0; C]\n}\nfn gram_matrix(_k: &[f32], _n: usize) -> Vec<f32> {\n    vec![0.0; C * C]\n}\nfn solve_cholesky(_kk: &[f32]) -> Vec<f32> {\n    vec![0.0; C]\n}\nfn build_uw(_k: &[f32], _b: &[f32], _n: usize, _g: &[f32], _i: &[f32]) -> (Vec<f32>, Vec<f32>) {\n    (vec![0.0; C], vec![0.0; C])\n}\nfn output_attention(_u: &[f32], _state: &[f32]) -> Vec<f32> {\n    vec![0.0; C]\n}\nfn state_update(_s: &mut [f32], _w: &[f32], _a: &[f32]) {}\nfn write_out(_o: &mut [f32], _n: usize, _a: &[f32]) {}\nfn sync() {}".to_string(),
        },

        // ── F: tree mask arrives as per-row bit words; the CTA unions
        // visibility across its query rows and SKIPS 32-key blocks no row
        // can see — the measured ≤384-row dispatch cross-over vs cuDNN is
        // the rule's own regime boundary. ────────────────────────────────
        KernelRule {
            rule_id: "ancestor-mask-bit-visibility-block-skip-tree-attention".to_string(),
            gpu_concept: "MECHANISM (bit-visibility block skip under a tree mask): when attention rows carry an ANCESTOR mask packed as per-row bit words (vbits[n][w] — one bit per visible key block), the CTA unions visibility across its 16 query rows and skips whole 32-key blocks that NO row can see: the union is a handful of ORs over the bit words, and a zero word retires the block's QK^T + softmax + PV work before it starts. The kernel body is FA-2-style online softmax in the exp2 domain with the sigmoid gate fused. THE MEASURED DISPATCH ARM IS THE RULE (source-measured on their B300, provenance never our bar): the kernel beats cuDNN SDPA only at <= 384 packed rows (288 rows: 12.7 vs 21.4 us); at 576 rows cuDNN wins (35.2 vs 34.2 us) — the cross-over IS the regime boundary, so the dispatch predicate carries it rather than a tuning table: below the bar the bit-skip kernel pays for its extra index work by skipping the invisible blocks a dense SDPA must compute; above it the dense vendor path's raw throughput wins. REGIME: tree/prefix-structured attention where the mask arrives as per-row bit words and significant fractions of keys are invisible to whole query groups (prefix-tree multi-candidate scoring: shared ancestors visible to every candidate, sibling subtrees invisible); query-row groups sharing a CTA (the union across 16 rows is what makes whole blocks skippable). ANTI-REGIME (three arms): full/dense attention with no invisible structure (a vendor SDPA/FA path is the whole answer — there is nothing to skip); row counts past the measured cross-over (cuDNN-class dense SDPA wins, source-measured); fusing the q/k PREP into the attention kernel — the source's own fattn2 variant was REJECTED at 36.7 us ('rejected: slower' class, the gated-RMSNorm negative's twin: the prep pays as a separate kernel because its output is shared across candidate paths). KINSHIP (do not double-count): mask-block-classification-skip-placement = the CAUSAL-mask 3-class scan+placement rule (classify -inf/zero/mixed tiles; here the mask is an ANCESTOR BITMAP — visibility is looked up, not classified by scanning values, and the skip unit is the 32-key block); dense-fast-path-bounded-by-selector-coverage = dense substitution bounded by a selector's reach (this SKIPS under a bitmap rather than substituting dense GEMM); split-k-two-pass-attention-decode-long-context = the long-context accumulation split (orthogonal axis — composes); fixed-ref-softmax-decode-walk = the softmax statistics form (this kernel keeps online FA-2 softmax). CITE: lyuyiqi/open-jev-fast @ c52b8bb9 -- src/kernels.cu fattn_k (round 4 C8) + the r4 bench logs (288 rows 12.7 vs 21.4 us; 576 rows 35.2 vs 34.2 us), MIT. Batch 189 / Plan 185 / Research 221 (candidate 2, B). RIDER (Batch 199 / Plan 197, ashhart/tensorfold @ c4646171 (v0.6.0, Apache-2.0) -- the ANALYTIC-band member, GLM DFlash2's block attention): where THIS rule skips blocks under a per-row BITMAP (visibility looked up, measured <=384-row cross-over vs cuDNN), TensorFold's _dattn_kernel skips the band ANALYTICALLY from position arithmetic -- a contiguous sliding window needs no mask words at all. The docstring names the whole contract (dflash2.py:92, verbatim): 'Each KV head attends its queries to the window's tiles (masked tiles skipped, same bits) and the block's keys.' and the skip is ONE clamped tile-floor (dflash2.py:109, verbatim): 'lo = tl.maximum(s - window, 0) // BK * BK' replacing the unconditional lo = 0. The bit-identity argument is the MASK SEMANTICS (commit 7c088eb, message-only): 'The skipped tiles are masked for every query and leave the running max, sum and accumulator bit for bit as they were (max(-1e30, -inf) = -1e30, alpha = 1, p = 0); the tiles run are the same tiles at the same offsets, so the output is the same bits' -- a fully-masked tile cannot move the online-softmax state, so skipping it is exact BY CONSTRUCTION, never by tolerance (the sibling draft-context-ring-window-bounded, same commit, bounds the CONTEXT side; this rider is the READ-SIDE band). No dispatch cross-over exists on this member: the skip wins wherever window < context (their DGX Spark kernel-only figures, provenance: block attention 16.2 -> 0.20 ms at 196k context, 43 -> 0.20 ms at 524k). The two members partition the skip axis by VISIBILITY SOURCE: bitmap (per-row ORs, cross-over-bounded dispatch -- this rule) vs analytic band (position arithmetic, unconditional while window < context -- the rider); a mask that is part bitmap part window decomposes per block class. Verified verbatim at the pin (dflash2.py:92 + :109 exact; the timing figures commit-message-only, never a bar). Batch 199 rider.".to_string(),
            ref_shape: "// NAIVE: the tree attention runs the FULL key range through\n// online softmax for every query row — the ancestor mask is applied\n// as a per-element -inf add AFTER the score is computed, so invisible\n// sibling-subtree keys cost a full QK^T + exp + PV each.\nconst KEYS: usize = 512; // 16 blocks of 32\n\npub fn tree_attn_dense(\n    q: &[f32],\n    k: &[f32],\n    v: &[f32],\n    vbits: &[u32], // per-row visibility bit words (1 bit per block)\n    out: &mut [f32],\n) {\n    for (n, o) in out.iter_mut().enumerate() {\n        let mut m = f32::NEG_INFINITY;\n        let mut l = 0.0f32;\n        let mut acc = 0.0f32;\n        for t in 0..KEYS {\n            let score = q[n] * k[t];\n            // mask applied PER ELEMENT: invisible keys still pay the\n            // multiply, the exp call sits behind a branch, PV runs\n            let visible = (vbits[n] >> (t / 32)) & 1 == 1;\n            let s = if visible { score } else { f32::NEG_INFINITY };\n            if s > m {\n                m = s;\n            }\n        }\n        for t in 0..KEYS {\n            let visible = (vbits[n] >> (t / 32)) & 1 == 1;\n            if visible {\n                let s = q[n] * k[t];\n                let e = exp2f(s - m);\n                l += e;\n                acc += e * v[t]; // invisible blocks: full work, zero value\n            }\n        }\n        *o = if l > 0.0 { acc / l } else { 0.0 };\n    }\n}\n\nfn exp2f(_x: f32) -> f32 {\n    0.0\n}".to_string(),
            opt_pattern: "// OPT: the CTA UNIONs visibility across its query rows first — a\n// handful of ORs over the bit words — and a zero word SKIPS the\n// 32-key block before any QK^T issues. The dispatch arm carries the\n// MEASURED cross-over: bit-skip kernel <= 384 packed rows, vendor\n// SDPA above (288 rows 12.7 vs 21.4 us; 576 rows 35.2 vs 34.2 us,\n// source-measured).\nconst BLOCK: usize = 32; // keys per visibility bit\n\npub fn dispatch_tree_attn(rows_packed: usize) -> bool {\n    // the cross-over IS the dispatch predicate (source-measured bar;\n    // re-measure per GPU + SDPA alternative before adoption)\n    rows_packed <= 384\n}\n\npub fn tree_attn_block_skip(\n    q: &[f32],\n    k: &[f32],\n    v: &[f32],\n    vbits: &[u32], // one bit word per ROW, one bit per 32-key block\n    out: &mut [f32],\n) {\n    let n_blocks = k.len() / BLOCK;\n    for (n, o) in out.iter_mut().enumerate() {\n        // CTA-level union across the 16 query rows: block b is skippable\n        // only when NO row in the group can see it\n        let mut union = 0u32;\n        for r in vbits.iter().take(16) {\n            union |= *r;\n        }\n        let mut m = f32::NEG_INFINITY;\n        let mut l = 0.0f32;\n        let mut acc = 0.0f32;\n        for b in 0..n_blocks {\n            if (union >> b) & 1 == 0 {\n                continue; // INVISIBLE to every row: QK^T + exp + PV all\n            } // skipped before starting — zero work, not masked work\n            let visible = (vbits[n] >> b) & 1 == 1;\n            for t in b * BLOCK..(b + 1) * BLOCK {\n                let s = q[n] * k[t];\n                let s = if visible { s } else { f32::NEG_INFINITY };\n                if s > m {\n                    m = s;\n                }\n            }\n        }\n        for b in 0..n_blocks {\n            if (union >> b) & 1 == 0 {\n                continue;\n            }\n            let visible = (vbits[n] >> b) & 1 == 1;\n            for t in b * BLOCK..(b + 1) * BLOCK {\n                if visible {\n                    let e = exp2f(q[n] * k[t] - m);\n                    l += e;\n                    acc += e * v[t];\n                }\n            }\n        }\n        *o = if l > 0.0 { acc / l } else { 0.0 };\n    }\n}\n\nfn exp2f(_x: f32) -> f32 {\n    0.0\n}".to_string(),
        },

        // ── B: bf16 inputs span exactly 65,536 values — build the SiLU and
        // sigmoid tables ONCE at load; the hot kernel is a gather,
        // bit-exact to the reference. Anti-arm = the source's OWN
        // gated-RMSNorm-into-GDN-epilogue negative (slower). ─────────────
        KernelRule {
            rule_id: "exact-bf16-domain-activation-lut".to_string(),
            gpu_concept: "MECHANISM (full-domain exact table substitution): a bf16 input spans exactly 65,536 bit patterns, so a scalar unary transcendental on bf16 inputs — SiLU returning bf16, sigmoid returning f32 — can be replaced by a 65,536-entry table built ONCE at load by evaluating the reference implementation over every input pattern; the hot kernel becomes a GATHER indexed by the raw 16-bit pattern, bit-exact to the reference BY CONSTRUCTION (the table entry IS the reference output — 'sigmoid_f inline: identical to the table entry', source-verified). This sidesteps the per-site form-validation hazard entirely: where inline evaluation must re-validate any alternative transcendental form at the exact call site, vector width, and silicon (the fused-vector-site rule's contract), the LUT carries the validated output as data — the form question never reaches the hot path. REGIME: scalar unary transcendental ops whose INPUT is 16-bit (bf16/f16) and whose call sites are hot enough to amortize a one-time 65,536-entry build (256 KiB f32 / 128 KiB bf16 per function); identical inputs repeat across a batch (the gather hits L1/L2). ANTI-REGIME (two arms, both measured by the source): (a) f32 inputs — 2^32 patterns is infeasible, keep inline evaluation; (b) THE FOLD BEATS THE TABLE when folding REMOVES the op entirely — the source measured gated-RMSNorm folded into the GDN epilogue with inline sigmoid REJECTED AS SLOWER (their GDN_VER 5 'rejected: slower'), so the LUT wins exactly where the activation STANDS ALONE and loses wherever an epilogue fusion would delete it — price the fusion FIRST, then the table for what survives. KINSHIP (do not double-count): exhaustive-domain-input-patch-bit-identity = the same 16-bit-domain-is-exhaustively-sweepable enabler applied to PATCH an existing approximation's divergent inputs (this REPLACES the whole evaluation with the reference table — full substitution, not divergence patching; the two compose: patch what stands, table what is hot); fused-vector-site-transcendental-form-nonportable = per-site FORM selection within inline evaluation (this REPLACES evaluation with a table keyed on the full input domain — the complementary arm of the same hazard, and notably immune to it); bit-exact-dispatch-fusion-boundary-emulation = preserving roundings across a FUSED DISPATCH CHAIN (no chain here — a standalone op substitution); lut16-pshufb-byte-expansion-at-stage = a 16-entry SUBSET-SUM table expanded by shuffle inside a staging loop (a small-domain arithmetic decomposition, not a full-domain exact transcendental); the popcorn ternary subset-sum LUTs = few-entry arithmetic tables (same distance again); fp16-log-domain / denorm-scale = numeric-REGIME rules for inline evaluation. CITE: lyuyiqi/open-jev-fast @ c52b8bb9 -- src/kernels.cu act_tables_k + silu_mul_lut_k + the GDN_VER 5 rejection note in src/fastmodel.py, MIT. Batch 189 / Plan 185 / Research 221 (candidate 3, B). RIDER (Batch 199 / Plan 197, ashhart/tensorfold @ c4646171 (v0.6.0, Apache-2.0) -- the act_mode constexpr specialization, EXL3 grouped experts' SwiGLU): the inline-evaluation COMPLEMENT of this rule -- where the LUT carries the reference's OUTPUTS as data, the act_mode axis carries the reference's ROUNDING CHAIN as code. The axis is a two-value constant (experts.py:14, verbatim): 'ACT_BF16, ACT_F32 = 0, 1          # SwiGLU with the GLM family's bf16 roundings / in fp32' selected per call ('act_mode: int = ACT_F32' experts.py:174; GLM's lane passes ACT_BF16) and threaded to the kernel's epilogue, whose comment names both arms (experts.cu:118, verbatim): '// Program (member row, 128-block of the width): splits summed in order, rotated, * svh, SwiGLU (0: GLM's bf16 roundings, 1: fp32), then Xd = fp16((act * suh_d) @ H).' The bf16 arm transcribes the roundings VERBATIM -- every intermediate round-trips through the helper '__device__ __forceinline__ float bf16r(float x) { return __bfloat162float(__float2bfloat16_rn(x)); }' (experts.cu:117): 'act = bf16r(bf16r(gg / (1.f + expf(-gg))) * uu);' against the fp32 arm's unrounded 'act = gg / (1.f + expf(-gg)) * uu;' (experts.cu:142-150, both clamped by the same limit). The parity bar is the REFERENCE ENGINE ITSELF: tests/cuda/test_exl3_experts.py test_glm_small_bit_identical + test_glm_shaped_bit_identical run 'act_mode=experts.ACT_BF16' and assert 'torch.equal(y.view(torch.int32), y_glm.view(torch.int32))' against GLM's own EXL3 path -- bit-identical, never tolerance. The two arms of one exactness law: ENUMERATE the domain and store the outputs (this rule), or ENUMERATE THE ROUNDINGS and re-execute them in order (this rider); a rounding chain with k intermediates is a 2^k-space contract, which is why the transcription is PINNED to a reference rather than derived from a description. Verified verbatim at the pin (experts.py:14/:174; experts.cu:117-118/:142-150; the two test names + the torch.equal assert). Batch 199 rider. RIDER (Batch 242 / Plan 244 / Research 274 — ddalcu/mlx-serve @ 1015f7854fd8ee5c22e34993aaddee2443b9cfbf, MIT): the TABLE-AS-FUSION-ENABLER face — this rule's anti-regime arm (b) prices LUT vs epilogue-fold as ALTERNATIVES ('price the fusion FIRST, then the table for what survives'); mlx-serve COMPOSES them: when the fold happens anyway, the exact-domain table rides INTO the fused kernel, because the inline transcendental is what would break the fused-vs-composed parity. The fused MoE gate+up gather, verbatim (deepseek_v4.zig:1984-1988): 'The transformer.zig `gatherQmvGateUp` body with dsv4's clipped SwiGLU tail: accumulators round to T exactly where the composed gather_qmm pair wrote T(acc), then the f32 clip chain with the sigmoid read from an exact bf16-indexed table of mlx_sigmoid values (the swigluSigTable rule — a metal::exp transcendental is a rounding apart from the metallib).' The kernel-side ladder, verbatim (deepseek_v4.zig:2038-2039): 'Round exactly where the composed pair wrote T(acc), then the f32 clip chain: gate clips HIGH only, up clips both sides (reference).' over 'T gt = T(acc_g); T ut = T(acc_u);' then 'float sig = sigtab[as_type<ushort>(T(gc))];' (:2046) — the gather index is the raw bf16 bit pattern of the T-rounded clipped gate, so the fused kernel's activation input IS the composed chain's stored value and the table replaces the transcendental the metallib would round differently. The builder, verbatim (deepseek_v4.zig:2072-2074): 'f32 sigmoid over every bf16-representable input, computed ONCE by mlx_sigmoid itself (256 KB) so the kernel's activation cannot disagree with the composed chain's transcendental. Never freed: process-lifetime.' — built by evaluating the REFERENCE op over all 65,536 patterns ('const bits: u32 = @as(u32, @intCast(i)) << 16; // bf16 → f32 is exact widening', :2081), this rule's own full-domain construction. Second instance, same law (moe_affine4.zig:58, the Qwen3.8-Flash-Next arm): 'y[size_t(e) * N + row0 + r] = (gt * sigtab[as_type<ushort>(gt)]) * T(u);' — the table consumed inside the gather epilogue on a second model family. THE COMPOSED LAW: this rule's two arms are a PIPELINE, not alternatives — the fold deletes the activation where it can; where the fold KEEPS it, the table is what makes the fold bit-honest (even a perfectly mirrored rounding ladder diverges if the exp itself rounds apart — 'a metal::exp transcendental is a rounding apart from the metallib'). Distinct from this rule's standalone-LUT posture, from the B199 act_mode rider (the rounding chain as CODE — here the chain's transcendental is DATA), and from bit-equal-fusion-mirrors-reference-reduction-regime (B242, entries_gpu_99 — the geometry/rounding-POINT mirror; THIS supplies the transcendental-substitution half the mirror cannot reach). Batch 242 rider.".to_string(),
            ref_shape: "// NAIVE: the activation evaluates the transcendental inline at\n// every element — exp/tanh per call site, per form, re-validated\n// (or NOT re-validated) per site, vector width, and silicon.\npub fn silu_mul_inline(x_bf16: &[u16], y_bf16: &[u16], out: &mut [u16], n: usize) {\n    for i in 0..n {\n        let x = bf16_to_f32(x_bf16[i]);\n        let silu = x / (1.0 + (-x).exp()); // inline transcendental, per\n        let y = bf16_to_f32(y_bf16[i]); // element, per call site — the\n        out[i] = f32_to_bf16(silu * y); // form-validation hazard rides it\n    }\n}\n\npub fn sigmoid_inline(x_bf16: &[u16], out: &mut [f32], n: usize) {\n    for i in 0..n {\n        let x = bf16_to_f32(x_bf16[i]);\n        out[i] = 1.0 / (1.0 + (-x).exp()); // same hazard, f32 out\n    }\n}\n\nfn bf16_to_f32(_h: u16) -> f32 {\n    0.0\n}\nfn f32_to_bf16(_x: f32) -> u16 {\n    0\n}".to_string(),
            opt_pattern: "// OPT: bf16 spans exactly 65,536 bit patterns — build the SiLU\n// (bf16 out) and sigmoid (f32 out) tables ONCE at load by evaluating\n// the reference over EVERY pattern; the hot kernel is a gather,\n// bit-exact by construction (the entry IS the reference output).\nconst BF16_PATTERNS: usize = 65_536;\n\npub struct ActTables {\n    pub silu_bf16: Vec<u16>, // silu(x) as bf16 — bf16 in, bf16 out\n    pub sigmoid_f32: Vec<f32>, // sigmoid(x) as f32 — bf16 in, f32 out\n}\n\npub fn build_act_tables() -> ActTables {\n    let mut t = ActTables {\n        silu_bf16: vec![0u16; BF16_PATTERNS],\n        sigmoid_f32: vec![0.0f32; BF16_PATTERNS],\n    };\n    for p in 0..BF16_PATTERNS {\n        let x = bf16_to_f32(p as u16);\n        // the REFERENCE implementation produces every entry — the\n        // table is validated as data, once, not per call site\n        t.silu_bf16[p] = f32_to_bf16(x / (1.0 + (-x).exp()));\n        t.sigmoid_f32[p] = 1.0 / (1.0 + (-x).exp());\n    }\n    t\n}\n\npub fn silu_mul_lut(\n    t: &ActTables,\n    x_bf16: &[u16],\n    y_bf16: &[u16],\n    out: &mut [u16],\n    n: usize,\n) {\n    for i in 0..n {\n        let silu = bf16_to_f32(t.silu_bf16[x_bf16[i] as usize]); // gather\n        let y = bf16_to_f32(y_bf16[i]);\n        out[i] = f32_to_bf16(silu * y);\n    }\n}\n\npub fn sigmoid_lut(t: &ActTables, x_bf16: &[u16], out: &mut [f32], n: usize) {\n    for i in 0..n {\n        out[i] = t.sigmoid_f32[x_bf16[i] as usize]; // gather, bit-exact\n    }\n}\n\n// ANTI-ARM (source-measured, GDN_VER 5): folding the gated RMSNorm\n// into the GDN epilogue with inline sigmoid was REJECTED AS SLOWER —\n// the LUT wins where the activation STANDS ALONE; where an epilogue\n// fusion would DELETE the op, price the fusion first.\nfn bf16_to_f32(_h: u16) -> f32 {\n    0.0\n}\nfn f32_to_bf16(_x: f32) -> u16 {\n    0\n}".to_string(),
        },

        // ── D: CUDA Graphs cached per (path, row-bucket, candidates,
        // path-bucket) key, LRU-capped; inputs copied in at replay — the
        // capture cost amortizes across every request that lands in the\n// bucket. ──────────────────────────────────────────────────────────
        KernelRule {
            rule_id: "shape-bucketed-graph-cache-lru".to_string(),
            gpu_concept: "MECHANISM (bucketed graph-cache amortization): cache one captured CUDA Graph per (execution path, row-BUCKET, candidate count, path-bucket) key — the row axis BUCKETED (buckets of 32 rows) rather than exact, so a bounded number of captures serves an unbounded request population — with an LRU cap (512 entries here) bounding device memory, and INPUTS COPIED INTO the graph's captured buffers at replay (the positive instance of cuda-graph-scalar-via-device-pointer: a captured graph bakes buffer ADDRESSES, so varying data rides fixed addresses through a copy-in, never a re-capture). Capture cost 1-3 s amortizes across the bucket's lifetime: the FIRST request of a bucket pays capture, every later request replays it at launch-overhead cost. Three decision contents. (1) The bucket axes are the axes that CHANGE THE PLAN, not the data: execution path (which kernels run), row bucket (grid shapes), candidate count, path bucket — data varies inside the fixed buffers. (2) LRU eviction, not unbounded growth: a graph holds device memory for every intermediate it captured, so the cache needs a memory-bounded cap and an eviction order; the cap is a memory budget, not a perf knob. (3) The replay contract is copy-in: varying inputs are memcpy'd into the captured input buffers before launch — a scalar knob that a captured kernel reads must ride a device buffer the graph already captured (the device-pointer-scalar law), never a host argument the bake froze. REGIME: serving loops with recurring shape classes (multi-candidate scoring requests land in few row buckets) on CUDA-graph-capable runtimes where per-launch overhead dominates small kernels (the source's whole ladder: ~5000 -> 945 -> 642 launches). ANTI-REGIME: shapes that never repeat (every capture wasted); graphs exceeding the LRU's memory budget at the recurring shapes (eviction thrash — capture cost repaid every request); paths whose INPUT LAYOUTS vary per request (the copy-in contract breaks — re-capture per layout is the death spiral the bucket exists to avoid). KINSHIP (do not double-count): cuda-graph-scalar-via-device-pointer = the SCALAR-via-device-buffer law this rule's replay half is a positive instance of (cited, not re-stated); graph-exec-update-gated-by-captured-topology-signature = the graph UPDATE path (share one exec via signature-matched update instead of re-capture — an alternative to eviction this composes with); captured-graph-bakes-buffer-addresses = the hazard law (bake freezes addresses — the reason copy-in exists); monomorphic-hot-caller-last-hit-memo = the tiny single-slot memo for MONOMORPHIC callers (this is the bounded-multi-key LRU for POLYMORPHIC shape classes). CITE: lyuyiqi/open-jev-fast @ c52b8bb9 -- src/server.py Entry/EntryState + _graphs (row-bucket 32, path-bucket 16, LRU 512, capture 1-3 s), MIT. Batch 189 / Plan 185 / Research 221 (candidate 4, B-).".to_string(),
            ref_shape: "// NAIVE: every request builds and launches its own kernel\n// sequence — per-launch overhead paid per request, and any CUDA\n// graph captured for one request is thrown away with it.\npub fn serve_uncached(req: &Request, model: &Model) -> Vec<f32> {\n    let plan = model.plan_for(req.path, req.rows, req.candidates);\n    // a FRESH capture per request: capture cost 1-3 s repaid every time,\n    // or (worse) no graph at all and ~5000 per-launch overheads\n    let graph = capture_graph(&plan, req.rows);\n    copy_inputs(&graph, req);\n    graph.replay();\n    read_outputs(&graph)\n}\n\nstruct Request {\n    path: usize,\n    rows: usize,\n    candidates: usize,\n}\nstruct Model;\nimpl Model {\n    fn plan_for(&self, _p: usize, _r: usize, _c: usize) -> Plan {\n        Plan\n    }\n}\nstruct Plan;\nstruct Graph;\nimpl Graph {\n    fn replay(&self) {}\n}\nfn capture_graph(_p: &Plan, _rows: usize) -> Graph {\n    Graph\n}\nfn copy_inputs(_g: &Graph, _r: &Request) {}\nfn read_outputs(_g: &Graph) -> Vec<f32> {\n    vec![]\n}".to_string(),
            opt_pattern: "// OPT: one captured graph per (path, row-BUCKET, candidates,\n// path-bucket) key — the row axis bucketed so bounded captures serve\n// unbounded request shapes — LRU-capped for memory, inputs COPIED\n// INTO the captured buffers at replay (never a re-capture for data).\nconst ROW_BUCKET: usize = 32; // rows round UP into the bucket's graph\nconst LRU_CAP: usize = 512; // memory-bounded, not a perf knob\n\npub struct Entry {\n    pub path: usize,\n    pub row_bucket: usize, // (rows + ROW_BUCKET - 1) / ROW_BUCKET\n    pub candidates: usize,\n    pub path_bucket: usize,\n}\n\npub struct GraphCache {\n    order: Vec<Entry>, // LRU: most-recent at the back\n    graphs: Vec<Graph>, // captured graphs, parallel to `order`\n}\n\nimpl GraphCache {\n    pub fn replay(&mut self, req: &Request, model: &Model) -> Vec<f32> {\n        let key = Entry {\n            path: req.path,\n            row_bucket: req.rows.div_ceil(ROW_BUCKET), // BUCKET the row\n            candidates: req.candidates, // axis — data varies inside the\n            path_bucket: req.path / 16, // captured buffers, never the key\n        };\n        if let Some(pos) = self.order.iter().position(|e| {\n            e.path == key.path\n                && e.row_bucket == key.row_bucket\n                && e.candidates == key.candidates\n                && e.path_bucket == key.path_bucket\n        }) {\n            // hit: move to MRU, copy-in, replay — launch overhead only\n            let entry = self.order.remove(pos);\n            self.order.push(entry.clone());\n            let g = &self.graphs[pos];\n            copy_inputs(g, req); // the replay contract: varying data\n            g.replay(); // rides fixed captured addresses\n            return read_outputs(g);\n        }\n        // miss: capture ONCE (1-3 s), amortized across the bucket's\n        // lifetime; evict LRU past the memory-bounded cap\n        let plan = model.plan_for(key.path, key.row_bucket * ROW_BUCKET, key.candidates);\n        let g = capture_graph(&plan, key.row_bucket * ROW_BUCKET);\n        if self.order.len() >= LRU_CAP {\n            self.order.remove(0); // evict LRU — graphs hold device memory\n            self.graphs.remove(0);\n        }\n        self.order.push(key);\n        self.graphs.push(g);\n        let g = self.graphs.last().expect(\"just pushed\");\n        copy_inputs(g, req);\n        g.replay();\n        read_outputs(g)\n    }\n}\n\nstruct Request {\n    path: usize,\n    rows: usize,\n    candidates: usize,\n}\nstruct Model;\nimpl Model {\n    fn plan_for(&self, _p: usize, _r: usize, _c: usize) -> Plan {\n        Plan\n    }\n}\nstruct Plan;\nstruct Graph;\nimpl Graph {\n    fn replay(&self) {}\n}\nfn capture_graph(_p: &Plan, _rows: usize) -> Graph {\n    Graph\n}\nfn copy_inputs(_g: &Graph, _r: &Request) {}\nfn read_outputs(_g: &Graph) -> Vec<f32> {\n    vec![]\n}".to_string(),
        },

        // ── D: the annotation row — the source's measured-NEGATIVE ledger.
        // Five rejected levers, each with its measured reason, so a future
        // fork experiment on a fused serving stack does not re-run them.
        // Refutation-type (the vectorized-smem-write class): the rule\n        // exists to STOP the re-try. ─────────────────────────────────────
        KernelRule {
            rule_id: "fused-serving-stack-measured-negative-ledger".to_string(),
            gpu_concept: "REFUTATION-TYPE (the folk-wisdom-stopper class): a fused CUDA serving backend for a 27B GDN+FA hybrid measured FIVE levers to rejection on its own stack (B300; provenance, never our bar) — this entry exists so the next fork experiment reads the ledger BEFORE re-running them. (1) GATED-RMSNORM INTO THE GDN EPILOGUE: 'rejected: slower' (their GDN_VER 5) — folding the norm+sigmoid into the recurrence kernel lost to the separate pass; the LUT rule's own anti-arm. (2) L2 WEIGHT PREFETCH: '+0.18 ms, no GEMM gain' (their PF env knob) — prefetching weights into L2 ahead of the GEMMs bought nothing on a B300-class machine; contrast the REGISTER-prefetch ring's measured WIN at <= 6-bit k-steps (register-prefetch-ring-measured-cutoff — the level distinction is the content: L2-level prefetch of large weight streams lost where the register-level ring of small packed steps won; do not transfer either verdict across the level boundary). (3) PROGRAMMATIC DEPENDENT LAUNCH: rejected — PDL's overlap did not pay on this stack (a rejection INSTANCE beside the capability-gated PDL rider on cooperative-tensor-mma-capability-route: the launch attribute is available and still not worth it here). (4) EXHAUSTIVE cuBLASLt ALGO SEARCH: rejected as unnecessary — 'the large GEMMs were already optimal' under heuristic timing (the source ships lt.cpp, a per-shape algo-timing wrapper, and still concluded heuristics suffice) — an INSTANCE of the tuning-effort-vs-return ceiling, kin to exhaustive-search-unnecessary doctrine. (5) FP8 GEMMs: measured 14.6 -> 7.8 ms and REJECTED ON NUMERICS — the lossy-surface law (per-family conditional retention before any bit-changing transform; an aggregate speedup on drifted outputs is a speedup of a wrong result). PLUS (6) persistent-kernel-not-the-winner and (7) prep-fused-into-attention (fattn2 'rejected: 36.7 us') — carried as anti-arms on the rules they bound (the tree-attention rule's prep arm; the persistent-kernel datum rides here). The ledger discipline: each row is a MEASURED negative on THEIR silicon and THEIR model — a datum, not a law; the re-open bar is a changed regime (different GPU class, different model shape), never 'try again harder'. KINSHIP: occupancy-grid-cap-refuted-uncapped-default + persistent-kernel-family negatives = the same stopper class; the L2/FP8/PDL/cuBLASLt rows have no prior corpus home — that is the gap this entry fills. CITE: lyuyiqi/open-jev-fast @ c52b8bb9 -- src/fastmodel.py env-knob rejection notes + bench/logs/r4/ + src/lt.cpp, MIT. Batch 189 / Plan 185 / Research 221 (the annotation row).".to_string(),
            ref_shape: "// NAIVE: a fresh fork experiment re-tries every folk-wisdom lever\n// on the fused serving stack — L2 prefetch, PDL, an exhaustive\n// cuBLASLt sweep, FP8 GEMMs, the epilogue fold — paying the full\n// measure-and-reject cycle each time.\npub fn tune_stack_fresh() -> TuningReport {\n    let mut report = TuningReport::default();\n    try_l2_weight_prefetch(&mut report); // re-measured: +0.18 ms, no\n    try_programmatic_dependent_launch(&mut report); // gain (rejected)\n    try_exhaustive_cublaslt_search(&mut report); // 'already optimal'\n    try_fp8_gemm(&mut report); // 14.6 -> 7.8 ms, REJECTED on numerics\n    try_gdn_epilogue_norm_fold(&mut report); // 'rejected: slower'\n    report\n}\n\n#[derive(Default)]\nstruct TuningReport;\n\nfn try_l2_weight_prefetch(_r: &mut TuningReport) {}\nfn try_programmatic_dependent_launch(_r: &mut TuningReport) {}\nfn try_exhaustive_cublaslt_search(_r: &mut TuningReport) {}\nfn try_fp8_gemm(_r: &mut TuningReport) {}\nfn try_gdn_epilogue_norm_fold(_r: &mut TuningReport) {}".to_string(),
            opt_pattern: "// OPT (the ledger, not a code change): the five levers below are\n// MEASURED NEGATIVES on the source's fused serving stack — read the\n// ledger BEFORE re-running any of them; the re-open bar is a CHANGED\n// REGIME (GPU class / model shape), never 'try again harder'.\n#[derive(Default)]\nstruct TuningReport;\n\npub const MEASURED_NEGATIVES: &[(&str, &str)] = &[\n    (\n        \"l2-weight-prefetch\",\n        \"+0.18 ms, no GEMM gain — the L2-level prefetch of large weight \\\n         streams lost; the REGISTER-level ring (<= 6-bit steps) is a \\\n         DIFFERENT level and its win does not transfer down\",\n    ),\n    (\n        \"programmatic-dependent-launch\",\n        \"rejected — PDL's overlap did not pay on this stack (the launch \\\n         attribute was available and still not worth it)\",\n    ),\n    (\n        \"exhaustive-cublaslt-search\",\n        \"unnecessary — 'the large GEMMs were already optimal' under \\\n         heuristic timing; the per-shape wrapper shipped and heuristics \\\n         still sufficed\",\n    ),\n    (\n        \"fp8-gemm\",\n        \"14.6 -> 7.8 ms measured AND REJECTED ON NUMERICS — the \\\n         lossy-surface law: no bit-changing transform without \\\n         per-family conditional retention\",\n    ),\n    (\n        \"gated-rmsnorm-into-gdn-epilogue\",\n        \"'rejected: slower' (GDN_VER 5) — the fold lost to the separate \\\n         pass; the activation LUT wins only where the op STANDS ALONE\",\n    ),\n];\n\npub fn consult_the_ledger_before_the_next_fork_experiment() -> usize {\n    MEASURED_NEGATIVES.len() // 5 rows: read before every fork experiment\n}".to_string(),
        },
    ]
}
